* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Open Sans', sans-serif;
    line-height: 1.6;
    color: #e0e0e0;
    background-color: #121212;
}

a {
    text-decoration: none;
    color: #6daa2c;
}

ul {
    list-style: none;
}

