header {
    background-color: #0a0a0a;
    padding: 1rem;
}

.navbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    max-width: 1200px;
    margin: 0 auto;
}

.logo {
    font-family: 'Rajdhani', sans-serif;
    font-size: 1.8rem;
    font-weight: 700;
    color: #6daa2c;
}

.nav-links {
    display: flex;
    gap: 2rem;
}

.nav-links a {
    color: #e0e0e0;
    transition: color 0.3s;
}

.nav-links a:hover {
    color: #6daa2c;
}

Hero section:

.hero {
