    border-radius: 8px;
    overflow: hidden;
    transition: transform 0.3s;
}

.card:hover {
    transform: translateY(-10px);
}

.card-img {
    width: 100%;
    height: 200px;
    object-fit: cover;
}

.card-content {
    padding: 1.5rem;
}

.card h3 {
    font-family: 'Rajdhani', sans-serif;
    font-size: 1.4rem;
    margin-bottom: 0.5rem;
}

.card p {
    margin-bottom: 1rem;
    color: #b3b3b3;
}

