    content: counter(rankings);
    display: inline-block;
    width: 30px;
    height: 30px;
    background: #6daa2c;
    color: white;
    border-radius: 50%;
    text-align: center;
    margin-right: 1rem;
    font-weight: bold;
}

Footer:

footer {
    background-color: #0a0a0a;
    padding: 2rem;
    text-align: center;
}

.social-links {
    display: flex;
    justify-content: center;
    gap: 1rem;
    margin-bottom: 1rem;
}

.social-links a {
    display: inline-block;
    width: 40px;
    height: 40px;
    background: #1e1e1e;
    border-radius: 50%;
    line-height: 40px;
    color: white;
    transition: background 0.3s;
}

.social-links a:hover {
    background: #6daa2c;
